"""Helpers for money amounts. Amounts are floats in US dollars."""


def round_money(amount: float) -> float:
    """Round a dollar amount to whole cents (half up)."""
    return round(amount + 1e-9, 2)


def format_money(amount: float) -> str:
    """Format a dollar amount for display, e.g. 1234.5 -> '$1,234.50'."""
    return f"${amount:,.2f}"

"""Product catalog."""

from dataclasses import dataclass


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    price: float  # unit price in US dollars


CATALOG: dict[str, Product] = {
    "MUG-01": Product("MUG-01", "Ceramic mug", 12.50),
    "TEE-01": Product("TEE-01", "Logo t-shirt", 19.99),
    "CAP-01": Product("CAP-01", "Baseball cap", 15.00),
    "BAG-01": Product("BAG-01", "Tote bag", 9.95),
}


def get_product(sku: str) -> Product:
    try:
        return CATALOG[sku]
    except KeyError:
        raise KeyError(f"unknown sku: {sku}") from None


def price_of(sku: str) -> float:
    """Unit price of a product, in US dollars."""
    return get_product(sku).price

"""Shopping cart."""

from shop.catalog import get_product, price_of
from shop.money import round_money


class Cart:
    def __init__(self) -> None:
        self._lines: dict[str, int] = {}  # sku -> quantity

    def add(self, sku: str, qty: int = 1) -> None:
        if qty <= 0:
            raise ValueError("quantity must be positive")
        get_product(sku)  # raises KeyError for unknown skus
        self._lines[sku] = self._lines.get(sku, 0) + qty

    def remove(self, sku: str) -> None:
        self._lines.pop(sku, None)

    def is_empty(self) -> bool:
        return not self._lines

    def lines(self) -> list[tuple[str, int]]:
        """(sku, quantity) pairs in the order they were added."""
        return list(self._lines.items())

    def subtotal(self) -> float:
        """Sum of unit price x quantity, in US dollars."""
        return round_money(sum(price_of(sku) * qty for sku, qty in self._lines.items()))

"""Shipping, tax and order quotes. All amounts are in US dollars."""

from shop.cart import Cart
from shop.money import round_money

TAX_RATES: dict[str, float] = {
    "US-CA": 0.0725,
    "US-NY": 0.04,
    "EU-DE": 0.19,
    "IN-KA": 0.18,
}

SHIPPING_FLAT = 5.00
FREE_SHIPPING_THRESHOLD = 50.00


def shipping_for(subtotal: float) -> float:
    return 0.0 if subtotal >= FREE_SHIPPING_THRESHOLD else SHIPPING_FLAT


def tax_for(subtotal: float, region: str) -> float:
    if region not in TAX_RATES:
        raise ValueError(f"unsupported region: {region}")
    return round_money(subtotal * TAX_RATES[region])


def quote(cart: Cart, region: str) -> dict[str, float]:
    """Price breakdown for a cart: subtotal, shipping, tax (on the subtotal) and total."""
    subtotal = cart.subtotal()
    shipping = shipping_for(subtotal)
    tax = tax_for(subtotal, region)
    return {
        "subtotal": subtotal,
        "shipping": shipping,
        "tax": tax,
        "total": round_money(subtotal + shipping + tax),
    }

"""A fake payment gateway. Like most real gateways, it takes integer cents."""

from dataclasses import dataclass


@dataclass(frozen=True)
class Charge:
    id: str
    customer_id: str
    amount_cents: int


class PaymentGateway:
    def __init__(self) -> None:
        self.charges: list[Charge] = []

    def charge(self, customer_id: str, amount_cents: int) -> str:
        if not isinstance(amount_cents, int) or isinstance(amount_cents, bool):
            raise TypeError("amount_cents must be an int")
        if amount_cents <= 0:
            raise ValueError("amount_cents must be positive")
        charge = Charge(f"ch_{len(self.charges) + 1:04d}", customer_id, amount_cents)
        self.charges.append(charge)
        return charge.id

    def total_charged(self, customer_id: str) -> int:
        return sum(c.amount_cents for c in self.charges if c.customer_id == customer_id)

